  final double? bpm;

  /// PERFECT window (± ms, real time). Default 80.
  final double perfectMs;

  /// Beyond this error a press counts as a miss. Default 600.
  final double missMs;
  final bool timed;

  const TutorialChart({
    required this.events,
    required this.lessons,
    this.bpm,
    required this.perfectMs,
    required this.missMs,
    required this.timed,
  });

  @override
  int get hashCode =>
      events.hashCode ^
      lessons.hashCode ^
      bpm.hashCode ^
      perfectMs.hashCode ^
      missMs.hashCode ^
      timed.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TutorialChart &&
          runtimeType == other.runtimeType &&
          events == other.events &&
          lessons == other.lessons &&
          bpm == other.bpm &&
          perfectMs == other.perfectMs &&
          missMs == other.missMs &&
          timed == other.timed;
}

class TutorialEvent {
  /// Song seconds at speed 1.0 (compare with `TransportClock.song_secs`).
  final double timeSecs;

  /// Target pad, or `None` when the step is a page switch.
  final PadId? pad;
  final Bank? pageSwitch;
  final ColorRole? color;
  final TutorialAction action;

  const TutorialEvent({
    required this.timeSecs,
    this.pad,
    this.pageSwitch,
    this.color,
    required this.action,
  });

  @override
  int get hashCode =>
      timeSecs.hashCode ^
      pad.hashCode ^
      pageSwitch.hashCode ^
      color.hashCode ^
      action.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TutorialEvent &&
          runtimeType == other.runtimeType &&
          timeSecs == other.timeSecs &&
          pad == other.pad &&
          pageSwitch == other.pageSwitch &&
          color == other.color &&
          action == other.action;
}

class TutorialLesson {
  final List<TutorialEvent> events;
  final double durationSecs;
  final double songStartSecs;

  const TutorialLesson({
    required this.events,
    required this.durationSecs,
    required this.songStartSecs,
  });

  @override
  int get hashCode =>
      events.hashCode ^ durationSecs.hashCode ^ songStartSecs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TutorialLesson &&
          runtimeType == other.runtimeType &&
          events == other.events &&
          durationSecs == other.durationSecs &&
          songStartSecs == other.songStartSecs;
}

/// Error returned by every fallible function (thrown in Dart).
class UpError implements FrbException {
  final ErrorCode code;
  final String message;

  const UpError({required this.code, required this.message});

  @override
  int get hashCode => code.hashCode ^ message.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UpError &&
          runtimeType == other.runtimeType &&
          code == other.code &&
          message == other.message;
}
